Perform a security review of this key-rotation implementation for timing attacks, improper key handling, and race conditions:
```go
func RotateKey(store KeyStore, newKey []byte) error {
    oldKey, _ := store.Get("active")
    if bytes.Equal(oldKey, newKey) {
        return errors.New("key unchanged")
    }
    store.Set("previous", oldKey)
    store.Set("active", newKey)
    go func() {
        time.Sleep(24 * time.Hour)
        store.Delete("previous")
    }()
    return nil
}
func Verify(store KeyStore, mac []byte, data []byte) bool {
    active, _ := store.Get("active")
    if hmac.Equal(computeMAC(data, active), mac) {
        return true
    }
    previous, _ := store.Get("previous")
    return string(computeMAC(data, previous)) == string(mac)
}
```

